/**
 * Booking Service - Global booking store
 * Manages booking flow state (selected services, time slot, location, form submission)
 * Persists across page navigation in SPA until page refresh
 */
import { defineService, implementService } from '@wix/services-definitions';
import { SignalsServiceDefinition, } from '@wix/services-definitions/core-services/signals';
import { executeBookAction } from './book-action/bookAction.js';
import { ClientServiceIds } from '../constants.js';
// ============================================================================
// Constants
// ============================================================================
// ============================================================================
// Helpers
// ============================================================================
/**
 * Generates a unique instance ID for service selections
 */
function generateInstanceId() {
    return crypto.randomUUID();
}
/**
 * Gets the client's timezone from Intl API
 */
function getClientTimezone() {
    return typeof Intl !== 'undefined'
        ? Intl.DateTimeFormat().resolvedOptions().timeZone
        : undefined;
}
/**
 * Service definition for Booking
 */
export const BookingServiceDefinition = defineService(ClientServiceIds.booking);
// ============================================================================
// Service Implementation
// ============================================================================
/**
 * Implementation of BookingService
 *
 * This service stores booking state in memory during the session.
 * State persists across page navigation (SPA behavior) until page refresh.
 *
 * @example
 * ```tsx
 * // In BaseLayout.astro
 * const bookingConfig = await loadBookingServiceConfig();
 *
 * // Wrap app with provider
 * <Booking.Root config={bookingConfig}>
 *   {children}
 * </Booking.Root>
 *
 * // In any page - access booking data
 * <Booking.Data>
 *   {({ serviceSelections, location, formSubmission, actions }) => (
 *     <div>{serviceSelections.map(item => item.service.name).join(', ')}</div>
 *   )}
 * </Booking.Data>
 * ```
 */
export const BookingService = implementService.withConfig()(BookingServiceDefinition, ({ getService, config }) => {
    const signalsService = getService(SignalsServiceDefinition);
    // Initialize signals with config values
    // Ensure all initial service selections have instanceIds
    const initialItemsWithIds = (config.serviceSelections || []).map((item) => ({
        ...item,
        instanceId: item.instanceId || generateInstanceId(),
    }));
    const serviceSelectionsSignal = signalsService.signal(initialItemsWithIds);
    const locationSignal = signalsService.signal(config.location || null);
    const timezoneSignal = signalsService.signal(config.timezone ?? getClientTimezone());
    const formSubmissionSignal = signalsService.signal(config.formSubmission || null);
    const selectedPaymentOptionSignal = signalsService.signal(config.selectedPaymentOption);
    const depositSelectedSignal = signalsService.signal(config.depositSelected);
    // Internal-only signal: set via `setAllDay`, read by `book()`. Not
    // exposed on the service surface — consumers derive and push the value
    // (e.g. from the picker's selection mode), so there's no read-back.
    const allDaySignal = signalsService.signal(false);
    // ========================================================================
    // Helpers
    // ========================================================================
    function getTargetItem(instanceId) {
        const current = serviceSelectionsSignal.get();
        const targetId = instanceId ?? current[0]?.instanceId;
        if (!targetId)
            return undefined;
        return current.find((item) => item.instanceId === targetId);
    }
    // ========================================================================
    // Actions Implementation
    // ========================================================================
    const actions = {
        // Item management actions
        setItem(item) {
            const instanceId = generateInstanceId();
            const newItem = {
                ...item,
                instanceId,
            };
            serviceSelectionsSignal.set([newItem]);
            return instanceId;
        },
        addItem(item) {
            const instanceId = generateInstanceId();
            const current = serviceSelectionsSignal.get();
            const newItem = {
                ...item,
                instanceId,
            };
            serviceSelectionsSignal.set([...current, newItem]);
            return instanceId;
        },
        updateItem(updates, instanceId) {
            const current = serviceSelectionsSignal.get();
            // If no instanceId provided, update the first item (index 0)
            const targetId = instanceId ?? current[0]?.instanceId;
            const updated = current.map((item) => item.instanceId === targetId ? { ...item, ...updates } : item);
            serviceSelectionsSignal.set(updated);
        },
        removeItem(instanceId) {
            const current = serviceSelectionsSignal.get();
            if (!instanceId) {
                // Remove first item if no instanceId provided
                serviceSelectionsSignal.set(current.slice(1));
            }
            else {
                const filtered = current.filter((item) => item.instanceId !== instanceId);
                serviceSelectionsSignal.set(filtered);
            }
        },
        clearItems() {
            serviceSelectionsSignal.set([]);
        },
        setResource(resource, instanceId) {
            const targetItem = getTargetItem(instanceId);
            if (!targetItem)
                return;
            const newResources = targetItem.resources
                .filter((r) => r.type !== resource.type)
                .concat(resource);
            this.updateItem({ resources: newResources, timeSlot: undefined }, targetItem.instanceId);
        },
        getResourceByType(resourceType, instanceId) {
            return getTargetItem(instanceId)?.resources.find((r) => r.type === resourceType);
        },
        clearResourceByType(resourceType, instanceId) {
            const targetItem = getTargetItem(instanceId);
            if (!targetItem)
                return;
            const newResources = targetItem.resources.filter((r) => r.type !== resourceType);
            this.updateItem({ resources: newResources }, targetItem.instanceId);
        },
        // Location actions
        setLocation(location) {
            locationSignal.set(location);
        },
        clearLocation() {
            locationSignal.set(null);
        },
        // Timezone actions
        setTimezone(timezone) {
            if (timezoneSignal.get() !== timezone) {
                timezoneSignal.set(timezone);
            }
        },
        // Form Submission actions
        setFormSubmission(values) {
            formSubmissionSignal.set(values);
        },
        clearFormSubmission() {
            formSubmissionSignal.set(null);
        },
        // Payment option action
        setSelectedPaymentOption(value) {
            selectedPaymentOptionSignal.set(value ?? undefined);
        },
        // Deposit vs full upfront action
        setDepositSelected(value) {
            depositSelectedSignal.set(value);
        },
        // All-day (DAY-range) action
        setAllDay(value) {
            allDaySignal.set(value);
        },
        // Clear all
        clearAll() {
            this.clearItems();
            this.clearLocation();
            this.clearFormSubmission();
            this.setAllDay(false);
        },
        // Book action - collects data from signals and delegates to executeBookAction
        // Loading/error state management is handled in Book.tsx component
        async book() {
            const serviceSelections = serviceSelectionsSignal.get();
            const formSubmission = formSubmissionSignal.get();
            const location = locationSignal.get();
            const timezone = timezoneSignal.get();
            const selectedPaymentOption = selectedPaymentOptionSignal.get();
            const depositSelected = depositSelectedSignal.get();
            const allDay = allDaySignal.get();
            // Validation happens inside executeBookAction
            return executeBookAction({
                serviceSelections,
                formSubmission,
                location,
                timezone,
                appId: config.appId,
                sourceAppId: config.sourceAppId,
                selectedPaymentOption,
                depositSelected,
                allDay,
            });
        },
    };
    return {
        serviceSelections: serviceSelectionsSignal,
        location: locationSignal,
        timezone: timezoneSignal,
        formSubmission: formSubmissionSignal,
        selectedPaymentOption: selectedPaymentOptionSignal,
        depositSelected: depositSelectedSignal,
        actions,
    };
});
